import java.io.*;

public class ChainDemo {
  static void multi() {
    try {
      if (System.nanoTime() % 2 == 0) throw new IOException("io");
      throw new InterruptedException("interrupted");
    } catch (IOException | InterruptedException e) {
      System.out.println("统一处理: " + e.getClass().getSimpleName());
    }
  }

  static void wrap() {
    try {
      throw new IOException("磁盘满");
    } catch (IOException e) {
      throw new RuntimeException("保存失败", e);   // 传 cause
    }
  }

  public static void main(String[] args) {
    multi();
    try { wrap(); } catch (RuntimeException e) {
      System.out.println("cause=" + e.getCause().getMessage());
    }
  }
}

public class FinallyDemo {
