}

public class ReturnDemo {
  static int prim() {
    int x = 1;
    try { return x; }
    finally { x = 99; }        // 不影响返回值
  }

  static StringBuilder ref() {
    StringBuilder sb = new StringBuilder("a");
    try { return sb; }
    finally { sb.append("b"); } // 影响对象内容
  }

  static int override() {
    try { return 1; }
    finally { return 2; }       // 覆盖返回值
  }

  public static void main(String[] args) {
    System.out.println(prim());
    System.out.println(ref());
    System.out.println(override());
  }
}

public class SwallowDemo {
  static int bad() {
    try {
      throw new IllegalStateException("重要错误");
    } finally {
      return 42;        // 异常被吞掉
    }
  }

  static int good() {
    boolean failed = false;
    try {
      throw new IllegalStateException("重要错误");
    } catch (IllegalStateException e) {
      failed = true;
      System.out.println("记录异常: " + e.getMessage());
      return -1;
    } finally {
      System.out.println("清理完成, failed=" + failed);
    }
  }

  public static void main(String[] args) {
    System.out.println(bad());
    System.out.println(good());
  }
}

import java.io.*;

public class TwrDemo {
  static class Res implements AutoCloseable {
    private final String name;
    Res(String name) { this.name = name; System.out.println("打开 " + name); }
    public void close() {
      System.out.println("关闭 " + name);
      throw new RuntimeException("关闭失败: " + name);
    }
  }

  public static void main(String[] args) {
    try (Res a = new Res("A"); Res b = new Res("B")) {
      System.out.println("使用中");
      throw new IllegalStateException("主异常");
    } catch (Exception e) {
      System.out.println("捕获: " + e.getMessage());
      for (Throwable s : e.getSuppressed()) {
        System.out.println("抑制: " + s.getMessage());
      }
    }
  }
}

