public <T> T retry(Supplier<T> action, int times) {
  RuntimeException last = null;
  for (int i = 0; i < times; i++) {
    try { return action.get(); }
    catch (RuntimeException e) {
      if (!isRetryable(e)) throw e;
      last = e;
    }
  }
  throw last;
}

